from collections import Counter
def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    res=[row[:] for row in g]
    for r in range(H):
        z=[c for c in range(W) if g[r][c]==bg]
        if not z: continue
        end=max(z)
        cnt=Counter(x for x in g[r] if x!=bg)
        maj=cnt.most_common()[0][0]
        for c in range(end+1,W):
            if g[r][c]==maj: res[r][c]=1
    return res
