from collections import deque
def comps(g,bg):
    H,W=len(g),len(g[0])
    res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg:
                comp=[(r,c)]; q=deque([(r,c)])
                seen={(r,c)}
                while q:
                    x,y=q.popleft()
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nxx,nyy=x+dx,y+dy
                        if 0<=nxx<H and 0<=nyy<W and g[nxx][nyy]!=bg and (nxx,nyy) not in seen:
                            seen.add((nxx,nyy)); comp.append((nxx,nyy)); q.append((nxx,nyy))
                res.append(comp)
    return res
